import { expect, test } from './browser-test.ts';
import { EXAMPLE_CODE } from '../src/game/game.fixture.ts';
import { DealControl, ReproductionControl } from '../src/game/controls/control-labels.ts';
import { GRID_SIZES } from '../src/game/deck.ts';
import { SessionNotice } from '../src/game/session/session.ts';
import { loadTimedBoard, exportedSnapshot, GAME_URL } from './game-fixture.ts';

// The published input limits, kept apart from the components that set them.
const BOARD_CODE_MAX_CHARACTERS = 32;
const SNAPSHOT_MAX_CHARACTERS = 65_536;

test('native reproduction controls keep drafts, limits, exact errors and action focus', async ({
  page,
}) => {
  await page.goto(GAME_URL);
  await expect(page.locator('details')).not.toHaveAttribute('open');
  await expect(page.locator('summary')).toHaveText(ReproductionControl.summary);
  const options = await page
    .getByLabel(DealControl.size, { exact: true })
    .locator('option')
    .evaluateAll((items) =>
      items.map((item) => {
        if (!(item instanceof HTMLOptionElement)) throw new Error('Expected a native option.');
        return { value: item.value, text: item.textContent };
      }),
    );
  expect(options).toEqual(
    GRID_SIZES.map((size) => ({ value: String(size), text: `${size}x${size}` })),
  );
  await loadTimedBoard(page);
  await page.locator('summary').click();
  const code = page.getByLabel(ReproductionControl.board, { exact: true });
  const field = page.getByLabel(ReproductionControl.snapshot, { exact: true });
  await expect(code).toHaveAttribute('maxlength', String(BOARD_CODE_MAX_CHARACTERS));
  await expect(field).toHaveAttribute('maxlength', String(SNAPSHOT_MAX_CHARACTERS));
  await code.fill('draft');
  await page.locator('.card').first().click();
  expect(await code.inputValue()).toBe('draft');
  const load = page.getByRole('button', { name: ReproductionControl.loadBoard, exact: true });
  await load.click();
  await expect(load).toBeFocused();
  await expect(page.locator('.load-notice')).toHaveText(SessionNotice.invalidBoard);
  await field.fill('{');
  const importButton = page.getByRole('button', {
    name: ReproductionControl.loadSnapshot,
    exact: true,
  });
  await importButton.click();
  await expect(importButton).toBeFocused();
  await expect(page.locator('.load-notice')).toHaveText(SessionNotice.invalidSnapshot);
  const exportButton = page.getByRole('button', {
    name: ReproductionControl.exportSnapshot,
    exact: true,
  });
  await exportButton.click();
  await expect(exportButton).toBeFocused();
  const text = await field.inputValue();
  expect(text).toContain('\n');
  await field.selectText();
  expect(
    await field.evaluate((element) => {
      if (!(element instanceof HTMLTextAreaElement)) throw new Error('Expected a textarea.');
      return element.selectionEnd - element.selectionStart;
    }),
  ).toBe(text.length);
  await code.fill(EXAMPLE_CODE);
  await load.click();
  await expect(load).toBeFocused();
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toMatchObject({ moves: 0, elapsedMs: 0, started: false });
});
import { expect, test } from './browser-test.ts';
import { loadTimedBoard, exportedSnapshot } from './game-fixture.ts';

test('literal control labels, limits and invalid statuses match the public contract', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await expect(page.locator('.stats > div').nth(3)).toHaveText('Best: none');
  await expect(page.locator('.stats dd[aria-label]')).toHaveCount(0);
  await expect(
    page.getByRole('combobox', { name: 'Grid size', exact: true }).locator('option'),
  ).toHaveText(['4x4', '6x6', '8x8', '10x10', '12x12', '14x14', '16x16']);
  for (const label of ['New Game', 'Restart'])
    await expect(page.getByRole('button', { name: label, exact: true })).toBeVisible();
  await expect(page.locator('details')).not.toHaveAttribute('open');
  await expect(page.locator('summary')).toHaveText('Reproduce a game');
  await page.locator('summary').click();
  await expect(page.getByLabel('Board code', { exact: true })).toHaveAttribute('maxlength', '32');
  await expect(page.getByLabel('Snapshot JSON', { exact: true })).toHaveAttribute(
    'maxlength',
    '65536',
  );
  for (const label of ['Load board', 'Export snapshot', 'Load snapshot'])
    await expect(page.getByRole('button', { name: label, exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: /replay/i })).toHaveCount(0);
  await page.locator('summary').click();
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await page.locator('.card').nth(0).click();
  await page.clock.runFor(1200);
  const before = await exportedSnapshot(page);
  expect(before).toMatchObject({
    matched: [2, 6],
    selection: { kind: 'one', index: 0 },
    moves: 1,
    elapsedMs: 1200,
  });
  await page.locator('summary').click();
  const board = page.getByLabel('Board code', { exact: true });
  await board.fill('invalid');
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
  await expect(page.locator('.load-notice')).toHaveText('Invalid board code.');
  await expect(board).toHaveValue('invalid');
  const snapshot = page.getByLabel('Snapshot JSON', { exact: true });
  await snapshot.fill('{');
  await page.getByRole('button', { name: 'Load snapshot', exact: true }).click();
  await expect(page.locator('.load-notice')).toHaveText('Invalid snapshot.');
  await expect(snapshot).toHaveValue('{');
  await page.locator('summary').click();
  expect(await exportedSnapshot(page)).toEqual(before);
  await page.clock.runFor(1000);
  expect((await exportedSnapshot(page)).elapsedMs).toBe(2200);
});

test('draft resets, load focus, paused notice and Resume focus order survive remembered positions', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(9).focus();
  await page.locator('summary').click();
  const board = page.getByLabel('Board code', { exact: true });
  for (const label of ['New Game', 'Restart']) {
    await board.fill('stale');
    await page.getByRole('button', { name: label, exact: true }).click();
    await expect(board).not.toHaveValue('stale');
    await expect(page.getByRole('button', { name: label, exact: true })).toBeFocused();
    await expect(page.locator('.card').first()).toHaveAttribute('tabindex', '0');
  }
  await page.locator('.card').nth(9).focus();
  await board.fill('stale');
  await page.getByLabel('Snapshot JSON', { exact: true }).fill(
    JSON.stringify({
      version: 1,
      boardCode: 'np1-4-1',
      matched: [],
      moves: 1,
      elapsedMs: 500,
      started: true,
      selection: { kind: 'closed' },
    }),
  );
  const load = page.getByRole('button', { name: 'Load snapshot', exact: true });
  await load.click();
  await expect(load).toBeFocused();
  await expect(board).toHaveValue('np1-4-1');
  await expect(page.locator('.card').first()).toHaveAttribute('tabindex', '0');
  await expect(page.locator('.load-notice')).toHaveText(
    'Loaded snapshot. Select Resume to continue.',
  );
  const resume = page.getByRole('button', { name: 'Resume', exact: true });
  await expect(resume).toBeVisible();
  await page.locator('.card').nth(3).focus();
  await page.evaluate(() => {
    document.addEventListener('focusin', (event) => {
      if (event.target instanceof Element && event.target.matches('.card'))
        document.body.dataset.resumePresentAtFocus = String(
          [...document.querySelectorAll('button')].some((b) => b.textContent === 'Resume'),
        );
    });
  });
  await resume.click();
  await expect(page.locator('.card').nth(3)).toBeFocused();
  await expect(page.locator('body')).toHaveAttribute('data-resume-present-at-focus', 'true');
  await expect(resume).toHaveCount(0);
});

test('export keeps populated progress running and exposes a static imported win', async ({
  page,
}) => {
  await loadTimedBoard(page);
  await page.locator('.card').nth(2).click();
  await page.locator('.card').nth(6).click();
  await page.locator('.card').nth(0).click();
  await page.clock.runFor(1200);
  const before = await exportedSnapshot(page);
  expect(await exportedSnapshot(page)).toEqual(before);
  await page.clock.runFor(1000);
  expect(await exportedSnapshot(page)).toMatchObject({ ...before, elapsedMs: 2200 });
  await page.locator('summary').click();
  await page.getByLabel('Snapshot JSON', { exact: true }).fill(
    JSON.stringify({
      version: 1,
      boardCode: 'np1-4-1',
      matched: Array.from({ length: 16 }, (_, i) => i),
      moves: 8,
      elapsedMs: 3000,
      started: true,
      selection: { kind: 'closed' },
    }),
  );
  await page.getByRole('button', { name: 'Load snapshot', exact: true }).click();
  await expect(page.locator('.victory')).toBeVisible();
  await expect(page.locator('.victory')).toHaveText(
    'Every pair found in 8 moves and 0:03. Well played.',
  );
  await expect(page.locator('.victory')).not.toHaveClass(/celebrate/);
  await expect(page.locator('.stats dd').nth(3)).toHaveText('none');
});
import { expect } from './browser-test.ts';
import type { Locator } from '@playwright/test';

export async function expectFocusInside(card: Locator): Promise<void> {
  const bounds = await card.evaluate((element) => {
    const viewport = element.closest('.board-viewport');
    if (!viewport) throw new Error('Missing board scroll area.');
    const outer = viewport.getBoundingClientRect();
    const inner = element.getBoundingClientRect();
    const style = getComputedStyle(element);
    const ring = parseFloat(style.outlineWidth) + parseFloat(style.outlineOffset);
    return {
      left: inner.left - ring - outer.left - viewport.clientLeft,
      top: inner.top - ring - outer.top - viewport.clientTop,
      right: outer.left + viewport.clientLeft + viewport.clientWidth - inner.right - ring,
      bottom: outer.top + viewport.clientTop + viewport.clientHeight - inner.bottom - ring,
      windowLeft: inner.left - ring,
      windowTop: inner.top - ring,
      windowRight: innerWidth - inner.right - ring,
      windowBottom: innerHeight - inner.bottom - ring,
    };
  });
  for (const [edge, value] of Object.entries(bounds))
    expect(value, `V19 full focus outline ${edge}`).toBeGreaterThanOrEqual(-0.25);
}

// Distances from the card to each edge of the board's scroll area, with the card's scroll margin.
export async function boardGaps(card: Locator) {
  return card.evaluate((element) => {
    const viewport = element.closest('.board-viewport');
    if (!viewport) throw new Error('Missing board scroll area.');
    const outer = viewport.getBoundingClientRect();
    const inner = element.getBoundingClientRect();
    return {
      margin: parseFloat(getComputedStyle(element).scrollMarginRight),
      left: inner.left - outer.left - viewport.clientLeft,
      right: outer.left + viewport.clientLeft + viewport.clientWidth - inner.right,
      top: inner.top - outer.top - viewport.clientTop,
      bottom: outer.top + viewport.clientTop + viewport.clientHeight - inner.bottom,
    };
  });
}

